DROP TABLE IF EXISTS `pegawai`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pegawai` (
  `id_pegawai` int unsigned NOT NULL AUTO_INCREMENT,
  `nip` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_pegawai` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `jabatan` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_skpd` int unsigned DEFAULT NULL,
  `id_ruangan` int unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_pegawai`),
  UNIQUE KEY `pegawai_nip_unique` (`nip`),
  KEY `pegawai_id_skpd_foreign` (`id_skpd`),
  KEY `pegawai_id_ruangan_foreign` (`id_ruangan`),
  CONSTRAINT `pegawai_id_ruangan_foreign` FOREIGN KEY (`id_ruangan`) REFERENCES `ruangan` (`id_ruangan`) ON DELETE SET NULL,
  CONSTRAINT `pegawai_id_skpd_foreign` FOREIGN KEY (`id_skpd`) REFERENCES `skpd` (`id_skpd`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1294 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
