  `tarif_retribusi` decimal(15,2) DEFAULT NULL,
  `target_penerimaan` decimal(15,2) DEFAULT NULL,
  `realisasi_penerimaan` decimal(15,2) DEFAULT NULL,
  `PAD` decimal(15,2) DEFAULT NULL,
  `biaya_pengurusan` decimal(15,2) DEFAULT NULL,
  `total_tarif_sewa` decimal(15,2) DEFAULT NULL,
  `satuan` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_retribusi`),
  KEY `retribusi_tanah_id_tanah_foreign` (`id_tanah`),
  CONSTRAINT `retribusi_tanah_id_tanah_foreign` FOREIGN KEY (`id_tanah`) REFERENCES `tanah` (`id_tanah`) ON DELETE CASCADE
