DROP TABLE IF EXISTS `tanah_histories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tanah_histories` (
  `id_history` bigint unsigned NOT NULL AUTO_INCREMENT,
  `id_tanah` int unsigned NOT NULL,
  `id_user` int unsigned DEFAULT NULL,
  `aksi` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `data_lama` json DEFAULT NULL,
  `data_baru` json DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `id_retribusi` int unsigned DEFAULT NULL,
  `nama_aktor` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `objek` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tanah',
  `foto_bukti` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id_history`),
  KEY `tanah_histories_id_tanah_foreign` (`id_tanah`),
  KEY `tanah_histories_id_retribusi_index` (`id_retribusi`),
  KEY `tanah_histories_id_user_foreign` (`id_user`),
  CONSTRAINT `tanah_histories_id_tanah_foreign` FOREIGN KEY (`id_tanah`) REFERENCES `tanah` (`id_tanah`) ON DELETE CASCADE,
  CONSTRAINT `tanah_histories_id_user_foreign` FOREIGN KEY (`id_user`) REFERENCES `users` (`id_user`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
